// ============================================================================
// tests/unit/sdl_scancode_dik_test.cpp -- SDL scan codes -> retail's key indices
// ============================================================================
// Phase D.4 SDL step I2. The SDL keyboard backend (src/platform/sdl/input_sdl.cpp) fills
// the 256 DirectInput scan-code bytes from SDL's state through kSdlScancodeToDik, and
// answers the legacy GetAsyncKeyState(vk) through kVirtualKeyToSdlScancode
// (src/platform/common/sdl_dik_tables.h, generated by tools/sdl_dik/gen_sdl_dik_tables.py).
// Retail's two lifted tables (src/engine/input/input_key_tables.h) then decide the key
// index, unchanged. Checked here against those very bytes:
//   * every key index the DirectInput path reaches, SDL reaches, and no other;
//   * a scan code DirectInput does not know lands on retail's index-104 alias;
//   * no DIK code is claimed twice;
//   * the legacy table lands each virtual key on its own index, except retail's six
//     own mismatches between its two tables;
//   * the poller's unpack, replayed on a buffer built the way ReadKeyboard builds it.
// SDL scan-code values are SDL_scancode.h's (SDL 3.4.18), spelled as numbers: no SDL
// header (D4_RULES C7).
// ============================================================================
#include "unit.h"

#include <cstdint>
#include <cstring>
#include <set>

#include "input/input_key_tables.h"
#include "sdl_dik_tables.h"

using Input::KeyTables::kIndexToVirtualKey;
using Input::KeyTables::kScanCodeToIndex;
using Platform::Input::kSdlScancodeCount;
using Platform::Input::kSdlScancodeToDik;
using Platform::Input::kVirtualKeyToSdlScancode;

namespace {

constexpr int kAlias = 0x68;   // retail's index 104, where unmapped scan codes land

// SDL_scancode.h values used by name below.
constexpr int kSdlA = 4, kSdlEscape = 41, kSdlReturn = 40, kSdlPause = 72,
              kSdlNumLock = 83, kSdlKpEnter = 88, kSdlLCtrl = 224, kSdlLShift = 225,
              kSdlLAlt = 226, kSdlLGui = 227, kSdlRCtrl = 228, kSdlRShift = 229,
              kSdlRAlt = 230;

int IndexOfSdl(int s) { return kScanCodeToIndex[kSdlScancodeToDik[s]]; }

// What ReadKeyboard writes for a set of held SDL scan codes.
void BuildDik(const std::set<int>& held, uint8_t dik[256]) {
    std::memset(dik, 0, 256);
    for (int s : held) dik[kSdlScancodeToDik[s]] = 0x80;
}

// The poller's unpack (input_device_update.cpp PlatformGetKeyboardState, retail
// 0x1800e1c60): out[kScanCodeToIndex[i]] = keys[i] & 0x80, i 0..255, last write wins.
void Unpack(const uint8_t dik[256], bool out[0x69]) {
    for (int i = 0; i < 0x69; ++i) out[i] = false;
    for (int i = 0; i < 256; ++i) out[kScanCodeToIndex[i]] = (dik[i] & 0x80) != 0;
}

}  // namespace

UNIT_TEST(sdl_dik_reaches_exactly_the_indices_directinput_reaches) {
    std::set<int> viaDik, viaSdl;
    for (int d = 1; d < 256; ++d)
        if (kScanCodeToIndex[d] != kAlias) viaDik.insert(kScanCodeToIndex[d]);
    for (int s = 0; s < kSdlScancodeCount; ++s)
        if (kSdlScancodeToDik[s] != 0 && IndexOfSdl(s) != kAlias) viaSdl.insert(IndexOfSdl(s));
    CHECK(viaDik == viaSdl);
    CHECK_EQ(static_cast<int>(viaDik.size()), 0x68 - 3);   // all but VK-only 0x3D / 0x43 / 0x44
    CHECK(viaDik.count(0x3D) == 0);
    CHECK(viaDik.count(0x43) == 0);
    CHECK(viaDik.count(0x44) == 0);
}

UNIT_TEST(sdl_dik_no_dik_code_claimed_twice) {
    std::set<int> seen;
    int mapped = 0;
    for (int s = 0; s < kSdlScancodeCount; ++s) {
        const int d = kSdlScancodeToDik[s];
        if (d == 0) continue;
        CHECK(seen.insert(d).second);
        ++mapped;
    }
    CHECK(mapped > 100);
}

UNIT_TEST(sdl_dik_known_keys) {
    CHECK_EQ(int(kSdlScancodeToDik[kSdlEscape]), 0x01);     // DIK_ESCAPE
    CHECK_EQ(IndexOfSdl(kSdlEscape), 0);                    // index 0 is Esc (VK 0x1B)
    CHECK_EQ(int(kSdlScancodeToDik[kSdlA]), 0x1E);          // DIK_A
    CHECK_EQ(int(kIndexToVirtualKey[IndexOfSdl(kSdlA)]), 0x41);   // 'A'
    CHECK_EQ(int(kSdlScancodeToDik[kSdlReturn]), 0x1C);     // DIK_RETURN
    CHECK_EQ(int(kSdlScancodeToDik[kSdlKpEnter]), 0x9C);    // DIK_NUMPADENTER
    CHECK_EQ(IndexOfSdl(kSdlKpEnter), 0x5D);
    // DirectInput's Pause is 0xC5; SDL's own Windows table calls 0xC5 NumLock.
    CHECK_EQ(int(kSdlScancodeToDik[kSdlPause]), 0xC5);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlNumLock]), 0x45);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlLCtrl]), 0x1D);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlRCtrl]), 0x9D);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlLShift]), 0x2A);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlRShift]), 0x36);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlLAlt]), 0x38);
    CHECK_EQ(int(kSdlScancodeToDik[kSdlRAlt]), 0xB8);
    CHECK_EQ(IndexOfSdl(kSdlLShift), 0x3E);                 // VK_LSHIFT's index
    CHECK_EQ(IndexOfSdl(kSdlRShift), 0x42);                 // VK_RSHIFT's index
}

UNIT_TEST(sdl_dik_unmapped_lands_on_the_104_alias) {
    CHECK_EQ(int(kSdlScancodeToDik[0]), 0);                 // SDL_SCANCODE_UNKNOWN
    CHECK_EQ(IndexOfSdl(0), kAlias);
    CHECK_EQ(int(kSdlScancodeToDik[300]), 0);               // nothing at 300
    CHECK_EQ(IndexOfSdl(300), kAlias);
    // The Windows key is a DIK DirectInput reports (0xDB) that retail aliases to 104.
    CHECK_EQ(int(kSdlScancodeToDik[kSdlLGui]), 0xDB);
    CHECK_EQ(IndexOfSdl(kSdlLGui), kAlias);
}

UNIT_TEST(sdl_dik_unpack_replay) {
    uint8_t dik[256];
    bool out[0x69];

    BuildDik({kSdlA, kSdlLShift}, dik);
    Unpack(dik, out);
    int down = 0;
    for (int i = 0; i < 0x69; ++i) down += out[i] ? 1 : 0;
    CHECK_EQ(down, 2);
    CHECK(out[IndexOfSdl(kSdlA)]);
    CHECK(out[0x3E]);

    // An unmapped key (and the Windows key) never shows: the loop's last write to the
    // alias index is DIK 0xFF, which no key produces. The same holds for DirectInput.
    BuildDik({kSdlLGui, 0, 300}, dik);
    Unpack(dik, out);
    for (int i = 0; i < 0x69; ++i) CHECK(!out[i]);

    BuildDik({}, dik);
    Unpack(dik, out);
    for (int i = 0; i < 0x69; ++i) CHECK(!out[i]);
}

UNIT_TEST(sdl_dik_legacy_vk_table_lands_on_its_own_index) {
    // Retail's own mismatches between its two tables (the generator's LEGACY_ONLY).
    const std::set<int> legacyOnly = {0x3C, 0x3D, 0x43, 0x44, 0x5D, 0x68};
    int checked = 0;
    for (int i = 0; i < 0x69; ++i) {
        const uint16_t* codes = kVirtualKeyToSdlScancode[kIndexToVirtualKey[i]];
        if (legacyOnly.count(i)) continue;
        CHECK(codes[0] != 0);
        for (int k = 0; k < 2; ++k) {
            if (codes[k] == 0) continue;
            CHECK_EQ(IndexOfSdl(codes[k]), i);
            ++checked;
        }
    }
    CHECK(checked >= 0x69 - 6);
    // The generic modifiers read either side.
    const uint16_t* shift = kVirtualKeyToSdlScancode[0x10];
    CHECK(std::set<int>({shift[0], shift[1]}) == std::set<int>({kSdlLShift, kSdlRShift}));
    const uint16_t* ctrl = kVirtualKeyToSdlScancode[0x11];
    CHECK(std::set<int>({ctrl[0], ctrl[1]}) == std::set<int>({kSdlLCtrl, kSdlRCtrl}));
    const uint16_t* alt = kVirtualKeyToSdlScancode[0x12];
    CHECK(std::set<int>({alt[0], alt[1]}) == std::set<int>({kSdlLAlt, kSdlRAlt}));
    // VK_RETURN is either Enter; VK_OEM_8 (index 104) is no US key.
    const uint16_t* ret = kVirtualKeyToSdlScancode[0x0D];
    CHECK(std::set<int>({ret[0], ret[1]}) == std::set<int>({kSdlReturn, kSdlKpEnter}));
    CHECK_EQ(int(kVirtualKeyToSdlScancode[0xDF][0]), 0);
    // The mouse-button VKs are not keys (the mouse path reads them, step I3).
    CHECK_EQ(int(kVirtualKeyToSdlScancode[0x01][0]), 0);
}
